26	const PROCESSING_FEE = 5;
27	
28	// Only the main item types. Components are priced separately: individually,
29	// or as a discounted block of 3 alike ones.
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	};
36	
37	const COMPONENT_TYPES = ["rune", "moonstone"];
38	const COMPONENT_BASE_PREMIUM = 25;
39	const BLOCK_SIZE = 3;
40	const BLOCK_BASE_PREMIUM = 60;
41	
42	const isComponent = (item: Item): boolean =>
43	  COMPONENT_TYPES.includes(item.type);
44	
45	// Modifiers are additive percentages of the UNMODIFIED base premium, never
46	// compounding multipliers, and are kept as exact fractions rather than float
47	// multipliers: 100 * 1.1 is 110.00000000000001 in IEEE-754. Only the final
48	// premium is rounded, so intermediate amounts stay fractional.
49	const percentOf = (amount: number, percent: number): number =>
50	  (amount * percent) / 100;
51	
52	const FIRST_INSURANCE_PERCENT = 10;
53	const CURSE_PERCENT = 50;
54	const HIGH_ENCHANTMENT_PERCENT = 30;
55	const HIGH_ENCHANTMENT_THRESHOLD = 5;
56	const LOYALTY_DISCOUNT_PERCENT = 20;
57	const LOYALTY_THRESHOLD_YEARS = 2;
58	
59	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
60	
61	// A group of exactly 3 alike components is offered at a block price. Any
62	// other count is priced per component.
63	const componentGroupPremium = (count: number): number =>
64	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
65	
66	// Components are priced per group of alike ones, so each distinct type is
67	// counted and priced on its own.
68	const componentsPremium = (components: Item[]): number => {
69	  const distinctTypes = new Set(components.map((component) => component.type));
70	
71	  return [...distinctTypes].reduce((sum, type) => {
72	    const alike = components.filter((component) => component.type === type);
73	    return sum + componentGroupPremium(alike.length);
74	  }, 0);
75	};
76	
77	// Splits a quote's items into the two independently-priced kinds, so the
78	// main/component distinction is decided in exactly one place.
79	const partitionByComponent = (
80	  items: Item[],
81	): { mainItems: Item[]; components: Item[] } => ({
82	  mainItems: items.filter((item) => !isComponent(item)),
83	  components: items.filter(isComponent),
84	});
85	
86	// Item-specific modifiers apply to the affected item's OWN base premium, not
87	// to the policy total. They are independent: a cursed, highly enchanted item
88	// carries both, so each item sums the surcharges that apply to it.
89	const isHighlyEnchanted = (item: Item): boolean =>
90	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
91	
92	const surchargesFor = (item: Item): number => {
93	  const base = basePremiumOf(item);
94	  const curse = item.cursed ? percentOf(base, CURSE_PERCENT) : 0;
95	  const enchantment = isHighlyEnchanted(item)
96	    ? percentOf(base, HIGH_ENCHANTMENT_PERCENT)
97	    : 0;
98	
99	  return curse + enchantment;
100	};
101	
102	const itemSpecificModifiers = (mainItems: Item[]): number =>
103	  mainItems.reduce((sum, item) => sum + surchargesFor(item), 0);
104	
105	// Policy-wide modifiers are percentages of the whole policy's base premium,
106	// taken from the UNMODIFIED base so item-specific modifiers never feed into
107	// them - that is what keeps modifiers additive instead of compounding.
108	// Discounts are negative terms.
109	const qualifiesForLoyalty = (customer: Customer): boolean =>
110	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
111	
112	const policyWideModifiers = (
113	  basePremium: number,
114	  customer: Customer,
115	): number => {
116	  const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
117	  const loyalty = qualifiesForLoyalty(customer)
118	    ? -percentOf(basePremium, LOYALTY_DISCOUNT_PERCENT)
119	    : 0;
120	
121	  return firstInsurance + loyalty;
122	};
123	
124	const quotePremium = (step: QuoteStep, customer: Customer): number => {
125	  const { mainItems, components } = partitionByComponent(step.items);
126	
127	  const basePremium =
128	    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
129	    componentsPremium(components);
130	
131	  const modifiers =
132	    itemSpecificModifiers(mainItems) + policyWideModifiers(basePremium, customer);
133	
134	  return basePremium + modifiers + PROCESSING_FEE;
135	};
136	
137	export const runScenario = (scenario: Scenario): ScenarioResult => ({
138	  results: scenario.steps.map((step) => ({
139	    premium: quotePremium(step, scenario.customer),
140	  })),
141	});
